package com.example.rokidkeyboardbridge;
import android.content.*;import org.json.*;import java.util.*;
/** Correlates explicit reservation IDs to one transfer batch; no retries or capture controls. */
final class ReservationProgress {
 static final String PROCESS=UUID.randomUUID().toString();
 static JSONArray rows(Context c)throws Exception{return new JSONArray(c.getSharedPreferences("reservation_progress",0).getString("items","[]"));}
 static void write(Context c,JSONArray rows)throws Exception{JSONArray next=new JSONArray();for(int i=Math.max(0,rows.length()-8);i<rows.length();i++)next.put(rows.get(i));if(!c.getSharedPreferences("reservation_progress",0).edit().putString("items",next.toString()).commit())throw new java.io.IOException("予約結果を保存できません");}
 static synchronized void begin(Context c,String id,String kind,String phase,String reason)throws Exception{if(!id.matches("[a-f0-9-]{36}")||!kind.matches("photo|meeting")||!phase.matches("ACCEPTED|REJECTED|EXPIRED"))throw new java.io.IOException("予約形式が不正です");JSONArray rows=rows(c);for(int i=0;i<rows.length();i++)if(id.equals(rows.getJSONObject(i).optString("id")))return;rows.put(new JSONObject().put("id",id).put("kind",kind).put("phase",phase).put("reason",reason).put("at",System.currentTimeMillis()).put("process",PROCESS));write(c,rows);}
 static synchronized void progress(Context c,JSONObject transfer)throws Exception{JSONArray rows=rows(c);for(int i=rows.length()-1;i>=0;i--){JSONObject row=rows.getJSONObject(i);if(!PROCESS.equals(row.optString("process"))||!row.optString("kind").equals(transfer.optString("kind"))||!row.optString("phase").matches("ACCEPTED|RUNNING"))continue;String batch=transfer.optString("batchId");if(row.has("batchId")&&!batch.equals(row.optString("batchId")))continue;row.put("batchId",batch).put("phase",transfer.optString("phase")).put("at",System.currentTimeMillis());for(String k:new String[]{"expected","confirmed","retained","failed","unitsExpected","unitsConfirmed"})row.put(k,transfer.optLong(k));row.put("reason",transfer.optString("phase").equals("FAILED")?"転送を完了できませんでした。原本と保存照合を確認してください":"保存確認 "+transfer.optLong("confirmed")+" / "+transfer.optLong("expected")+"件・削除尊重でグラス保持 "+transfer.optLong("retained")+"件");write(c,rows);return;}}
 static synchronized void unstarted(Context c,String kind){try{JSONArray rows=rows(c);for(int i=rows.length()-1;i>=0;i--){JSONObject row=rows.getJSONObject(i);if(PROCESS.equals(row.optString("process"))&&kind.equals(row.optString("kind"))&&row.optString("phase").equals("ACCEPTED")){row.put("phase","FAILED").put("reason","転送の開始を確認できませんでした").put("at",System.currentTimeMillis());write(c,rows);return;}}}catch(Exception ignored){}}
 static synchronized JSONArray snapshot(Context c){try{JSONArray rows=rows(c),out=new JSONArray();for(int i=0;i<rows.length();i++){JSONObject row=new JSONObject(rows.getJSONObject(i).toString());if(row.optString("phase").matches("ACCEPTED|RUNNING")&&!PROCESS.equals(row.optString("process")))row.put("phase","INTERRUPTED").put("reason","グラス再起動後のため結果を確認してください");row.remove("process");out.put(row);}return out;}catch(Exception e){return new JSONArray();}}
 private ReservationProgress(){}
}
